<template>
  <!--
    Full-page timeline view for a mission.

    Why a route, not a drawer:
      * The timeline is dense — JSON payloads expand to multi-line
        blocks, and a 520px drawer truncates them.  Full width gives
        the agent's tool args room to breathe.
      * Deep-linkable URL (``/doc-net/missions/:id/timeline``) so users
        can share a debug session.  Drawer state was ephemeral.
      * Browser back returns to the mission detail naturally; no
        extra close-button choreography that conflicted with row-click
        expansion (the previous bug — every badge click bubbled into
        the row's expand handler and closed the drawer).

    Click semantics fixed: only the chevron toggles the row, badges
    use ``@click.stop`` so they don't bubble.
  -->
  <q-page class="q-pa-md timeline-page">
    <!-- Header: back button, title, filters, refresh.
         Layout mirrors ``DocNetMissionDetail`` so the two pages share
         a header rhythm: back button flush-left, ``docnet-page-title``
         next to it, ``q-space`` pushing trailing controls right. -->
    <div class="mission-header row items-center q-mb-md">
      <q-btn
        flat
        round
        dense
        icon="arrow_back"
        :to="`/doc-net/missions/${missionId}`"
        replace
        class="q-mr-sm"
      >
        <q-tooltip>{{ $t('back') }}</q-tooltip>
      </q-btn>
      <!-- Title order matches ``DocNetMissionDetail``: mission name is
           the h2 (the entity is what identifies the page), with the
           page noun ("Timeline") as a small caption underneath.  The
           user already knows what view they're on from the route +
           the menu they clicked, so the page noun is secondary. -->
      <!-- Title block: h2 + badges share the FIRST line so the
           badges sit at h2 height, not floating between h2 and the
           "Timeline" caption underneath.  An earlier layout had
           badges as siblings of the whole title block, which made
           the flex row vertically center them between the two
           lines. -->
      <div class="timeline-title">
        <div class="row items-center no-wrap">
          <h2 class="docnet-page-title">
            {{ missionName || $t('timeline') }}
          </h2>
          <q-badge
            v-if="missionSourceLabel"
            color="blue-grey-3"
            text-color="blue-grey-9"
            :label="missionSourceLabel"
            class="q-ml-sm"
          />
          <StatusBadge
            v-if="missionStatus"
            :status="missionStatus"
            size="md"
            class="q-ml-sm"
          />
        </div>
        <div v-if="missionName" class="text-caption text-grey-7">
          {{ $t('timeline') }}
        </div>
      </div>
      <q-space />
    </div>

    <!-- Filter row.  Visually grouped with the timeline below it
         (``q-mb-sm`` keeps them tight) and separated from the
         header above (the header's ``q-mb-xl`` is the gap between
         "title metadata" and "data + its controls").  This reads
         the way Slack/Linear/GitHub do — the filter belongs to the
         list it acts on, not to the page header. -->
    <div class="row items-center q-mb-xl">
      <div class="timeline-filters">
        <q-btn-toggle
          :model-value="activeFilter"
          no-caps
          rounded
          unelevated
          toggle-color="primary"
          color="white"
          text-color="primary"
          :options="filterOptions"
          class="timeline-filter-toggle"
          @update:model-value="setFilter"
        />
      </div>
    </div>

    <!-- Empty / error states -->
    <div
      v-if="error && items.length === 0"
      class="q-pa-lg text-center text-negative"
    >
      <div class="q-mb-sm">{{ $t('failed_to_load_timeline') }}</div>
      <q-btn
        flat
        dense
        no-caps
        color="primary"
        :label="$t('retry')"
        @click="reload"
      />
    </div>

    <div
      v-else-if="!loading && items.length === 0"
      class="q-pa-lg text-center text-grey-7"
    >
      {{ $t('no_timeline_events') }}
    </div>

    <!-- Event list.
         Renders ascending (oldest at top, newest at bottom) to match
         the rest of the product (mission detail's task list, issue
         comments, chat-style log feeds).  Live events arriving via
         WS append at the bottom so the user's eye doesn't get yanked
         away from where they're reading.  "Load more" sits at the
         TOP because it loads older history — same mental model as
         scrolling up in Slack.  The backend still paginates DESC;
         we just reverse for display via ``displayItems``. -->
    <div v-else class="timeline-list">
      <!-- Infinite-scroll sentinel for older history.  Sits at the
           top of the list; when the user scrolls within ~200px of
           it, ``IntersectionObserver`` fires ``loadMore``.  No
           button needed — refresh handles the bottom edge, scroll
           handles the top.  This is the same pattern Slack/Discord
           use for backfilling history. -->
      <div ref="loadMoreSentinel" class="timeline-loadmore-sentinel">
        <!-- Only the loading indicator renders here.  No "end of
             history" terminator — once ``nextCursor`` clears, the
             oldest row is just the first row.  An explicit "no more
             events" message at the TOP of an ascending feed reads
             like "this is the start" pasted above the start, which
             is awkward.  Slack/Discord don't draw a terminator
             either — the empty space is the signal. -->
        <div v-if="loading && nextCursor" class="text-center text-caption text-grey-6 q-py-sm">
          <q-spinner-dots color="primary" size="20px" class="q-mr-xs" />
          {{ $t('loading') }}
        </div>
      </div>

      <template
        v-for="(item, idx) in displayItems"
        :key="item.event_id"
      >
        <!-- Restart divider.  Rendered as a horizontal rule with
             a centered label so the visual break between the
             cancelled run and the restart's fresh run is obvious
             when scrolling.  Without this, ``Mission restarted``
             reads as just another audit row in a long list, and
             readers miss that everything below is a NEW attempt
             on the same mission. -->
        <div v-if="item.kind === 'restarted'" class="timeline-restart-divider">
          <span class="timeline-restart-divider__rule" />
          <span class="timeline-restart-divider__label">
            <q-icon name="restart_alt" size="14px" class="q-mr-xs" />
            {{ renderSummary(item) }}
            <span class="timeline-restart-divider__time q-ml-sm">
              {{ formatTime(item.occurred_at) }}
            </span>
          </span>
          <span class="timeline-restart-divider__rule" />
        </div>

      <div
        v-else
        class="timeline-row"
      >
        <!-- Vertical rail -->
        <div class="timeline-rail">
          <div
            class="timeline-dot"
            :class="`bg-${iconColor(item)}`"
          >
            <q-icon
              :name="iconFor(item)"
              size="14px"
              color="white"
            />
          </div>
          <!-- Hide the rail line when the next row is a restart
               divider — the divider IS the visual break, the line
               connecting through it would defeat that. -->
          <div
            v-if="idx < displayItems.length - 1
              && displayItems[idx + 1].kind !== 'restarted'"
            class="timeline-line"
          />
        </div>

        <!-- Body -->
        <div class="timeline-body q-pb-md">
          <div class="row items-center no-wrap q-gutter-x-sm">
            <div class="col">
              <div class="text-body2 text-weight-medium">{{ renderSummary(item) }}</div>
              <div class="text-caption text-grey-7 row items-center timeline-caption">
                <span>{{ formatTime(item.occurred_at) }}</span>
                <span class="timeline-caption__sep">·</span>
                <!-- Actor identity.  Each branch shows a small icon
                     prefix at the same scale so all three actor types
                     read as visual peers — agent rows used to wear a
                     full chip while humans/system stayed bare text,
                     which made agent rows look "loud" by comparison.
                     The chip is now an inline icon + name pair, same
                     pattern for human (email) and system. -->
                <span
                  v-if="item.actor_type === 'agent' && item.actor_name"
                  class="timeline-actor row items-center no-wrap"
                >
                  <q-icon name="smart_toy" size="14px" class="timeline-actor__icon text-primary" />
                  <span>{{ item.actor_name }}</span>
                </span>
                <!-- Anyone with an ``actor_name`` who isn't an
                     agent renders with the human chip.  Falling
                     through to ``system`` when an email/handle is
                     present produced the misleading "system" caption
                     above a clearly-human-authored row (e.g. inbox
                     approvals, user-typed mission messages).  The
                     bare ``system`` chip is reserved for actorless
                     rows (process timeouts, scheduled triggers). -->
                <span
                  v-else-if="item.actor_name"
                  class="timeline-actor row items-center no-wrap"
                >
                  <q-icon name="person" size="14px" class="timeline-actor__icon text-blue-grey-6" />
                  <span>{{ item.actor_name }}</span>
                </span>
                <span v-else class="timeline-actor row items-center no-wrap">
                  <q-icon name="settings" size="14px" class="timeline-actor__icon text-grey-6" />
                  <span>{{ $t('docnet_actor_system') }}</span>
                </span>
                <!-- ``tool_name`` is already in the summary ("Tool: X")
                     for tool events; only show it in the caption for
                     non-tool rows that happen to carry it. -->
                <span v-if="item.tool_name && !isToolEvent(item)" class="q-ml-sm">
                  · <code>{{ item.tool_name }}</code>
                </span>
              </div>
            </div>
            <q-badge
              v-if="item.approval"
              :color="item.approval === 'human' ? 'green-7' : 'grey-6'"
              :label="$t(item.approval === 'human' ? 'actor_human' : 'auto')"
              @click.stop
            />
            <q-btn
              v-if="hasPayload(item)"
              flat
              dense
              round
              size="sm"
              :icon="expanded.has(item.event_id) ? 'expand_less' : 'expand_more'"
              @click.stop="toggleExpand(item.event_id)"
            >
              <q-tooltip>{{ expanded.has(item.event_id) ? $t('hide_details') : $t('show_details') }}</q-tooltip>
            </q-btn>
          </div>

          <!-- Inline "old → new" chip pair for any single-field delta
               (status flips, classification changes, etc.).  Driven by
               the shared ``inlineChange`` helper so the
               ``/doc-net/activities`` page and this timeline render
               deltas the same way.  Empty string when the payload
               isn't a clean single-key delta — chevron still reveals
               the raw JSON for those cases. -->
          <div
            v-if="deltaPair(item)"
            class="row items-center q-gutter-xs q-mt-xs"
          >
            <q-icon name="swap_horiz" size="14px" class="text-grey-7" />
            <!-- Status keys reuse the same ``<StatusBadge>`` mission and
                 issue cards use, so the timeline stays visually
                 consistent with the rest of the app.  Non-status
                 single-field deltas (e.g. classification, priority)
                 fall back to inline text — adding a typed badge for
                 every possible field would balloon scope. -->
            <template v-if="isStatusDelta(item)">
              <StatusBadge :status="deltaPair(item)!.from" size="sm" />
              <q-icon name="arrow_forward" size="14px" class="text-grey-7" />
              <StatusBadge :status="deltaPair(item)!.to" size="sm" />
            </template>
            <code v-else class="text-caption">
              {{ deltaPair(item)!.from }} → {{ deltaPair(item)!.to }}
            </code>
          </div>

          <!-- Tool call: structured args table.  Renders only when the
               agent actually passed arguments — empty-args calls (e.g.
               ``list_agents``) leave the row compact.  Keys are
               rendered as ``param: value`` pairs in a small mono
               grid; long values wrap.  The chevron still exposes the
               full raw payload (including ``tool_call_id`` etc.) for
               debugging. -->
          <div
            v-if="toolArgs(item)"
            class="timeline-args q-mt-xs"
          >
            <div
              v-for="(value, key) in toolArgs(item)"
              :key="key"
              class="row items-baseline no-wrap timeline-arg-row"
            >
              <div class="timeline-arg-key">{{ key }}</div>
              <div class="timeline-arg-value">{{ formatArgValue(value) }}</div>
            </div>
          </div>

          <!-- Tool result: success/failure chip + one-line preview.
               Avoids the JSON wall-of-text that dominates failures.
               Click the chevron for the full result payload. -->
          <div
            v-if="toolResult(item)"
            class="row items-center q-gutter-xs q-mt-xs timeline-tool-result"
          >
            <q-chip
              v-if="toolResult(item)!.success !== undefined"
              dense
              square
              :color="toolResult(item)!.success ? 'positive' : 'negative'"
              text-color="white"
              :icon="toolResult(item)!.success ? 'check' : 'close'"
              :label="$t(toolResult(item)!.success ? 'succeeded' : 'status_failed')"
            />
            <span
              v-if="toolResult(item)!.preview"
              class="text-caption text-grey-9 timeline-tool-result-preview"
            >
              {{ toolResult(item)!.preview }}
            </span>
          </div>

          <!-- Comment rows: render the agent's Markdown body as
               sanitized HTML (DOMPurify via ``renderMarkdown``).
               Collapsed shows a 280-char teaser of the persisted
               preview; expand triggers a lazy fetch of the full
               ``IssueComment.content`` from
               ``GET /issue-comments/{id}`` so the user sees the
               literal complete comment, not a still-truncated
               version of it.  While the fetch is in flight the
               teaser keeps rendering with a small spinner overlay
               so the row is never blank. -->
          <div
            v-if="commentInfo(item)"
            class="timeline-comment-wrap q-mt-xs"
            :class="{
              'timeline-comment-wrap--negative':
                commentInfo(item)!.accent === 'negative',
              'timeline-comment-wrap--positive':
                commentInfo(item)!.accent === 'positive',
              'timeline-comment-wrap--warning':
                commentInfo(item)!.accent === 'warning',
            }"
          >
            <!-- Inbox-act rows: the proposed tool call's args.
                 Always inline (no chevron gate) so HITL-approved
                 tool calls have the same scan rhythm as auto-
                 approved ``Tool: ...`` rows — both display
                 ``key: value`` args directly under the header.
                 Without this, the same data showed inline for
                 auto-approved tools but hidden behind a chevron
                 for human-approved ones; same content, two
                 different reading patterns.  The colored
                 blockquote below (when notes are present) shows
                 the human's message. -->
            <div
              v-if="inboxToolArgs(item)"
              class="timeline-args"
            >
              <div
                v-for="(value, key) in inboxToolArgs(item)"
                :key="key"
                class="row items-baseline no-wrap timeline-arg-row"
              >
                <div class="timeline-arg-key">{{ key }}</div>
                <div class="timeline-arg-value">{{ formatArgValue(value) }}</div>
              </div>
            </div>
            <blockquote
              v-if="commentInfo(item)!.html"
              class="timeline-comment"
              v-html="commentInfo(item)!.html"
            />
            <div
              v-if="commentInfo(item)!.loading"
              class="row items-center q-gutter-xs q-mt-xs text-caption text-grey-7"
            >
              <q-spinner size="14px" color="primary" />
              <span>{{ $t('loading_full_comment') }}</span>
            </div>
          </div>

          <!-- Raw JSON for power users / debug.  Always opt-in via
               chevron so the timeline stays scannable by default.
               Comment rows skip this — the chevron there toggles the
               rendered Markdown between teaser and full text instead,
               and rendering JSON below the rendered Markdown would
               just duplicate ``preview`` in escaped form. -->
          <pre
            v-if="
              expanded.has(item.event_id)
              && hasPayload(item)
              && !commentInfo(item)
            "
            class="timeline-payload q-mt-sm"
          >{{ formatPayload(item.payload) }}</pre>
        </div>
      </div>
      </template>

    </div>

    <q-inner-loading :showing="loading && items.length === 0" />
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useRouter } from 'vue-router';
import { storeToRefs } from 'pinia';

import type {
  DocNetMission,
  DocNetTimelineEvent,
} from 'src/@types/docnet';
import DocNetIssueService from 'src/services/docnet/DocNetIssueService';
import DocNetMissionService from 'src/services/docnet/DocNetMissionService';
import {
  actionColor,
  actionIcon,
  formatSummary,
  inlineChangePair,
} from 'src/utils/docnet/auditFormatting';
import {
  formatMissionSource,
  formatRelativeTime,
} from 'src/utils/docnet/formatting';
import { formatToolResultPreview } from 'src/utils/docnet/timelinePreview';
import { renderMarkdown } from 'src/utils/markdown';
import StatusBadge from 'src/pages/DocNet/shared/StatusBadge.vue';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import {
  DocNetGatewayEventType,
  type MissionProgressEvent,
} from 'src/types/websocket';

const PAGE_SIZE = 50;

export default defineComponent({
  name: 'DocNetMissionTimeline',

  components: {
    StatusBadge,
  },

  setup() {
    const router = useRouter();
    const missionStore = useDocNetMissionStore();
    const wsStore = useDocNetWebSocketStore();
    const { currentMission: mission } = storeToRefs(missionStore);
    return { router, missionStore, wsStore, mission };
  },

  data() {
    return {
      items: [] as DocNetTimelineEvent[],
      nextCursor: null as string | null,
      loading: false,
      error: false,
      expanded: new Set<string>(),
      activeKinds: null as string[] | null,
      // ``onMissionEvent`` returns an unsubscribe fn — store it so we
      // can call it on unmount.  Without this we'd leak handlers
      // every time the user navigates back to the timeline page.
      wsUnsubscribe: null as null | (() => void),
      // Per-comment full-body cache.  Keyed by comment_id (the
      // database PK), populated on first expand of the row.  Once
      // cached, every subsequent expand of the same comment skips
      // the network round-trip — useful for users who collapse and
      // re-expand while comparing siblings.  The activity row always
      // carries a truncated ``preview``; this cache holds the full
      // ``IssueComment.content`` from ``GET /issue-comments/{id}``.
      fullCommentBodies: {} as Record<string, string>,
      // ``Set`` of comment_ids currently being fetched.  Drives the
      // tiny loading indicator in the comment block while the lazy
      // fetch is in flight, and prevents duplicate requests when the
      // user double-clicks the chevron.
      loadingCommentIds: new Set<string>(),
      // ``IntersectionObserver`` for the top-of-list sentinel that
      // triggers backfill when the user scrolls near the top.  Held
      // here so ``beforeUnmount`` can disconnect it.
      loadMoreObserver: null as IntersectionObserver | null,
    };
  },

  computed: {
    missionId(): string {
      return String(this.$route.params.id || '');
    },
    missionName(): string {
      return (this.mission as DocNetMission | null)?.name ?? '';
    },

    /** Same source-label rule as ``DocNetMissionDetail``: maps
     * ``mission.source`` to a human-readable label ("Email",
     * "Mission Control", …) for the prefix badge.  Pass
     * ``$t`` so the label follows the active locale; falls
     * back to the hardcoded English string when the
     * ``source_<token>`` key isn't translated yet. */
    missionSourceLabel(): string {
      return formatMissionSource(
        this.mission as DocNetMission | null,
        (k: string) => this.$t(k),
      );
    },

    /** Mission status drives the ``<StatusBadge>``.  Empty string
     * (rather than null) so the template can ``v-if`` cleanly. */
    missionStatus(): string {
      return (this.mission as DocNetMission | null)?.status ?? '';
    },

    /** Ascending (oldest → newest) view of ``items``.
     *
     *  The backend paginates DESC for cursor efficiency — the first
     *  page contains the most recent events.  But the human-friendly
     *  reading order is chronological: top of the page is "earliest
     *  thing that happened", live events append at the bottom (where
     *  the user's eyes already are when watching a run unfold).
     *
     *  We reverse here rather than in the API for two reasons:
     *    1. The cursor's keyset still needs to walk DESC to fetch the
     *       *next older* page.  Switching the API to ASC would mean
     *       the first response would be the OLDEST events — useless
     *       for a deep-link to a long-running mission.
     *    2. ``Array.prototype.toReversed()`` is O(n) and runs once per
     *       reactive update; cheap relative to the DOM cost. */
    displayItems(): DocNetTimelineEvent[] {
      // ``toReversed`` keeps reactivity correct (returns a new array)
      // without mutating ``items`` itself, which the WS append path
      // still touches in DESC order.
      return [...this.items].reverse();
    },
    filterOptions(): { label: string; value: string }[] {
      // Mirrors ``DocNetMissionList.filterOptions`` shape (``q-btn-toggle``
      // contract) so the two pages share visual style.  The dimension
      // is different — kinds, not statuses — but the chrome stays the
      // same.  Kinds that aren't promoted to a filter still appear
      // under "All".
      return [
        { value: 'all', label: this.$t('all') },
        { value: 'tools', label: this.$t('docnet_tools') },
        { value: 'status', label: this.$t('timeline_filter_statuses') },
        { value: 'approvals', label: this.$t('approvals') },
      ];
    },

    activeFilter(): string {
      // Reverse-map the ``activeKinds`` array back to the toggle's
      // scalar value.  ``activeKinds === null`` is the "all" rest
      // case; everything else identifies its option by its first
      // canonical kind to keep the lookup O(1).
      if (this.activeKinds === null) return 'all';
      const first = this.activeKinds[0];
      if (first === 'tool_call') return 'tools';
      if (first === 'status_changed') return 'status';
      if (first === 'approved') return 'approvals';
      return 'all';
    },
  },

  watch: {
    missionId: {
      immediate: true,
      handler(id: string) {
        if (!id) return;
        // Mission detail may not be loaded yet (deep-link to timeline);
        // fetch it so the header can show the name.  Best-effort —
        // wrapped in try/catch so a fetch failure doesn't abort the
        // timeline load below.  Earlier versions called the wrong
        // method here (``fetchMissionById``); the resulting
        // ``TypeError`` killed the whole watcher and the timeline
        // never loaded on hard-reload.  Belt-and-braces guard now.
        if (!this.mission || this.mission.id !== id) {
          try {
            void this.missionStore.fetchMission(id, true).catch(() => {});
          } catch {
            // store method missing or threw synchronously — non-fatal,
            // we still want the timeline itself to load.
          }
        }
        this.subscribeToMission(id);
        void this.reload();
      },
    },
  },

  mounted() {
    // Top-of-list sentinel for backfill.  ``rootMargin: 200px`` fires
    // the load slightly *before* the sentinel hits the viewport so the
    // user never sees a hard stop at the top — the older events have
    // started loading by the time they would have run out.
    this.loadMoreObserver = new IntersectionObserver(
      (entries) => {
        if (!entries[0]?.isIntersecting) return;
        if (!this.nextCursor || this.loading) return;
        void this.loadMore();
      },
      { rootMargin: '200px 0px 0px 0px', threshold: 0 },
    );
    const el = this.$refs.loadMoreSentinel as HTMLElement | undefined;
    if (el) this.loadMoreObserver.observe(el);
  },

  beforeUnmount() {
    if (this.wsUnsubscribe) this.wsUnsubscribe();
    if (this.loadMoreObserver) this.loadMoreObserver.disconnect();
  },

  methods: {
    subscribeToMission(missionId: string): void {
      if (this.wsUnsubscribe) this.wsUnsubscribe();
      // eslint-disable-next-line no-console
      console.log('[Timeline] subscribing to mission', missionId);
      this.wsUnsubscribe = this.wsStore.onMissionEvent(
        missionId,
        (eventType: string, _data: MissionProgressEvent) => {
          // Only one event of interest on this page — refetch the
          // first page when the timeline gains a new entry.  Other
          // mission events (status, agent_start, ...) already write
          // their own audit_log row, which the same refetch picks up.
          if (eventType === DocNetGatewayEventType.MISSION_TIMELINE_APPENDED) {
            // eslint-disable-next-line no-console
            console.log('[Timeline] triggering refreshLatest', {
              loading: this.loading,
            });
            void this.refreshLatest();
          }
        },
      );
    },

    async reload(): Promise<void> {
      if (!this.missionId) return;
      this.loading = true;
      this.error = false;
      this.items = [];
      this.nextCursor = null;
      this.expanded.clear();
      try {
        const service = new DocNetMissionService();
        const resp = await service.getMissionTimeline(this.missionId, {
          limit: PAGE_SIZE,
          kinds: this.activeKinds ?? undefined,
        });
        this.items = resp.items;
        this.nextCursor = resp.next_cursor;
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[DocNetMissionTimeline] reload failed', err);
        this.error = true;
      } finally {
        this.loading = false;
      }
      // Initial render: drop the user at the bottom (newest event)
      // since that's the active edge of the conversation.  Without
      // this, deep-linking to /timeline on a long-running mission
      // would dump the user at "Mission created" 3 hours ago.
      await this.$nextTick();
      this.scrollToBottom();
    },

    /** Refresh after a WS poke — preserve already-loaded older pages
     *  so the user doesn't lose their scroll position.  If they were
     *  already pinned to the bottom (watching events flow in), keep
     *  them there as the new event renders below.  Otherwise leave
     *  the scroll alone — yanking a reading user to the bottom is
     *  exactly what newest-on-top feeds get wrong. */
    async refreshLatest(): Promise<void> {
      if (!this.missionId || this.loading) return;
      const wasAtBottom = this.isNearBottom();
      try {
        const service = new DocNetMissionService();
        const resp = await service.getMissionTimeline(this.missionId, {
          limit: PAGE_SIZE,
          kinds: this.activeKinds ?? undefined,
        });
        const headIds = new Set(
          resp.items.map((it: DocNetTimelineEvent) => it.event_id),
        );
        const tail = this.items.filter(
          (it: DocNetTimelineEvent) => !headIds.has(it.event_id),
        );
        this.items = [...resp.items, ...tail];
        if (this.nextCursor === null) this.nextCursor = resp.next_cursor;
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[DocNetMissionTimeline] refresh failed', err);
      }
      if (wasAtBottom) {
        await this.$nextTick();
        this.scrollToBottom();
      }
    },

    async loadMore(): Promise<void> {
      if (!this.missionId || this.loading || !this.nextCursor) return;
      // "Load more" sits at the top and loads OLDER events.  When
      // they're inserted, the document grows upward — without
      // anchoring, the viewport would jump to keep the same offset
      // from the top, leaving the user staring at the wrong row.
      // Capture the pre-fetch ``scrollHeight`` and after the new
      // rows render, shift ``scrollTop`` by the same delta so the
      // user's current row stays in the same screen position.
      const preHeight = this.documentScrollHeight();
      const preScroll = this.windowScrollY();
      this.loading = true;
      try {
        const service = new DocNetMissionService();
        const resp = await service.getMissionTimeline(this.missionId, {
          limit: PAGE_SIZE,
          cursor: this.nextCursor,
          kinds: this.activeKinds ?? undefined,
        });
        this.items.push(...resp.items);
        this.nextCursor = resp.next_cursor;
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[DocNetMissionTimeline] loadMore failed', err);
      } finally {
        this.loading = false;
        await this.$nextTick();
        const delta = this.documentScrollHeight() - preHeight;
        if (delta > 0) {
          window.scrollTo({ top: preScroll + delta, behavior: 'instant' as ScrollBehavior });
        }
      }
    },

    // ── Scroll helpers ──────────────────────────────────────────
    // The page scrolls inside the layout's window, not a custom
    // container — Quasar's standard ``q-page`` lets the document
    // body scroll.  These helpers wrap the window APIs so the
    // intent is named at the call site and so we have one place to
    // change if a future layout switches to a scoped scroll area.

    /** Total document height (inc. off-screen content). */
    documentScrollHeight(): number {
      return Math.max(
        document.documentElement.scrollHeight,
        document.body.scrollHeight,
      );
    },

    /** Current window scroll position (Y axis). */
    windowScrollY(): number {
      return window.scrollY ?? window.pageYOffset ?? 0;
    },

    /** Drop the user at the bottom of the document — used on the
     *  initial load (newest event is the active edge) and after a
     *  WS append IF the user was already pinned to the bottom. */
    scrollToBottom(): void {
      window.scrollTo({
        top: this.documentScrollHeight(),
        behavior: 'instant' as ScrollBehavior,
      });
    },

    /** True when the user is within ~120px of the bottom — the
     *  threshold that classifies them as "watching live" rather
     *  than "reading older history".  120px ≈ one event row +
     *  some breathing room.  Above the threshold, an arriving WS
     *  event MUST NOT scroll the page; below, scrolling them to
     *  the new bottom keeps the live-tail experience smooth. */
    isNearBottom(): boolean {
      const scrolledTo = this.windowScrollY() + window.innerHeight;
      return scrolledTo >= this.documentScrollHeight() - 120;
    },

    setFilter(value: string): void {
      // Resolve the toggle's scalar value back to the kind list the
      // backend filter expects.  Kept as an explicit map (rather than
      // dual-storing the array on the option) so the option-shape
      // stays compatible with ``q-btn-toggle``.
      const next: string[] | null =
        value === 'tools' ? ['tool_call', 'tool_result']
        : value === 'status' ? ['status_changed']
        : value === 'approvals' ? ['approved', 'rejected', 'commented', 'comment_added']
        : null;
      if (this.activeFilter === value) return;
      this.activeKinds = next;
      void this.reload();
    },

    toggleExpand(id: string): void {
      const wasExpanded = this.expanded.has(id);
      if (wasExpanded) this.expanded.delete(id);
      else this.expanded.add(id);
      // Force reactivity for the Set replacement.
      this.expanded = new Set(this.expanded);

      // Lazy-fetch the full comment body the first time a comment
      // row is expanded.  No-op for non-comment rows or for comments
      // we've already fetched.  Fire-and-forget — the template
      // re-renders once ``fullCommentBodies`` updates.
      if (!wasExpanded) {
        const item = this.items.find(
          (it: DocNetTimelineEvent) => it.event_id === id,
        );
        if (item) void this.ensureFullComment(item);
      }
    },

    /** Fetch the full ``IssueComment.content`` for a comment row, if
     *  we don't already have it cached.  Best-effort: a failure
     *  leaves the row falling back to the persisted preview, with
     *  no error message — the preview is still useful, and the
     *  failure mode is "you see less than the maximum, not nothing." */
    async ensureFullComment(item: DocNetTimelineEvent): Promise<void> {
      const isComment =
        item.kind === 'comment_added' || item.kind === 'commented';
      if (!isComment) return;
      const commentId = (item.payload as { comment_id?: unknown } | null)
        ?.comment_id;
      if (typeof commentId !== 'string' || !commentId) return;
      if (commentId in this.fullCommentBodies) return; // already fetched
      if (this.loadingCommentIds.has(commentId)) return; // in flight
      this.loadingCommentIds.add(commentId);
      this.loadingCommentIds = new Set(this.loadingCommentIds);
      try {
        const service = new DocNetIssueService();
        const comment = await service.getCommentById(commentId);
        if (comment && typeof comment.content === 'string') {
          this.fullCommentBodies = {
            ...this.fullCommentBodies,
            [commentId]: comment.content,
          };
        }
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[DocNetMissionTimeline] full-comment fetch failed', err);
      } finally {
        this.loadingCommentIds.delete(commentId);
        this.loadingCommentIds = new Set(this.loadingCommentIds);
      }
    },

    /** Worth offering an "expand" affordance for this row?
     *
     *  False when the payload only contains the delta we already
     *  rendered as ``<StatusBadge>`` pair — showing the same
     *  information twice (chips + raw JSON) is noise.  True for
     *  tool calls, comments, and anything else with content the
     *  inline render doesn't already surface.
     *
     *  Signature: a payload of exactly ``{old, new}`` (and nothing
     *  else) is fully represented by ``deltaPair`` once that pair
     *  is non-null.  If the delta isn't a clean single-key change
     *  (multi-field update, non-primitive values), keep the chevron
     *  so the user can still inspect the raw payload. */
    hasPayload(item: DocNetTimelineEvent): boolean {
      const payload = item.payload;
      if (!payload || Object.keys(payload).length === 0) return false;
      const keys = Object.keys(payload);

      // Approval/rejection/etc. action rows: the row header already
      // says "Approved/Rejected/... by <user>" — that's the entire
      // event.  The persisted payload only carries debug pointers
      // (``inbox_item_id``) and ``resolution_notes`` (often null).
      // Hide the chevron when there are no resolution notes worth
      // revealing.  When notes ARE present (user typed a reason),
      // keep the chevron so they're inspectable.
      //
      // Checked BEFORE the generic all-primitive-delta rule below
      // so that "approved with notes" still surfaces — the generic
      // rule would otherwise hide it (notes are primitive strings).
      // Inbox-act audit rows.  Note ``commented`` is overloaded:
      // ``IssueActivity`` rows with kind=commented are child-issue
      // comments (preview/comment_id payload, lazy-fetched body);
      // ``audit_logs`` rows with kind=commented are inbox act-on-
      // comment decisions (resolution_notes payload).  Disambiguate
      // on ``source`` — only the audit-log variant uses
      // resolution_notes.
      const isInboxActKind =
        item.kind === 'approved'
        || item.kind === 'rejected'
        || item.kind === 'reassigned'
        || item.kind === 'dismissed'
        || (item.kind === 'commented' && item.source === 'mission_audit')
        || (typeof item.kind === 'string' && item.kind.startsWith('acted:'));
      if (isInboxActKind) {
        // Inbox-act rows render args + notes inline (same scan
        // rhythm as auto-approved ``Tool: ...`` rows).  Nothing
        // is left for the chevron drawer except the raw payload
        // JSON — and that lives behind a separate debug-mode
        // affordance, not here.  Hide the chevron.
        return false;
      }

      // Audit rows that are nothing but ``{old, new}``:
      //   * Status flip with a clean delta → ``<StatusBadge>`` pair
      //     already renders both values; raw JSON duplicates them.
      //   * "Mission assigned to project X", "Project X created"
      //     etc. — the row's summary is the canonical render
      //     (e.g. it already resolves a UUID to a project name).
      //     Showing the bare UUID via JSON is noise, never signal.
      //
      // Rule: when the only payload keys are ``old`` and ``new`` AND
      // every leaf value on both halves is primitive (string, number,
      // boolean, or null), the summary + StatusBadge pair (when
      // applicable) already cover everything the JSON would.
      // Anything more complex (nested objects, arrays of structs)
      // keeps the chevron — there might be detail worth inspecting.
      // Agent-response rows are checked BEFORE the all-primitive
      // delta rule below: their payload IS ``{old: null, new: {text}}``
      // with primitive values, which would otherwise short-circuit
      // the chevron off — but the row's expand IS the only way to
      // read the agent's response (the header carries just a one-
      // line preview).  Same pattern used for ``approved`` rows
      // higher up.
      if (item.kind === 'agent_response' || item.kind === 'user_message') {
        const aPayload = payload as { new?: { text?: unknown } | null };
        const fullText = aPayload.new?.text;
        return typeof fullText === 'string' && !!fullText.trim();
      }

      const isOldNewOnly =
        keys.length === 2 && keys.includes('old') && keys.includes('new');
      if (isOldNewOnly && this._isAllPrimitiveDelta(payload)) return false;

      // Creation events: the summary always reads ``<Entity> created:
      // <name>``, which names the entity.  The ``new_values`` block
      // is starting state (status, type, etc.) that's not worth a
      // raw-JSON drawer — the user already sees the most informative
      // field (title/name) in the summary, and subsequent rows show
      // any subsequent state changes.  ``old`` is null by definition
      // for creates; that asymmetry also makes the inline-delta
      // render meaningless here.
      if (item.kind === 'created' || item.kind === 'issue_created') {
        return false;
      }

      // Comment events: collapsed rows render no body (header-only),
      // so the chevron is the only way to read the comment.  Always
      // expose it when a preview or ``comment_id`` is present.
      if (item.kind === 'comment_added' || item.kind === 'commented') {
        const cPayload = payload as {
          preview?: unknown;
          comment_id?: unknown;
        };
        const hasPreview =
          typeof cPayload.preview === 'string' && !!cPayload.preview.trim();
        const hasCommentId =
          typeof cPayload.comment_id === 'string' && !!cPayload.comment_id;
        return hasPreview || hasCommentId;
      }


      // Tool rows: hide the chevron when the payload is fully
      // represented by the inline render.
      //
      // EXCEPTION: human-approved tool rows always keep the chevron.
      // The whole point of HITL is that a human signed off on a
      // specific action with specific arguments — "what exactly did
      // I approve?" should have a one-click answer regardless of
      // payload shape.  Auto-approved rows fall back to the standard
      // hide-when-redundant rule to keep the timeline scannable for
      // the high-frequency case.
      // The ``human``-approval guarantee ("what did I approve?") is
      // already met by the inline render: args appear as a
      // key-value table at the top of the row regardless of approval
      // mode.  A chevron drawer over a standard-shape payload would
      // just duplicate the same data as raw JSON.  The chevron only
      // makes sense when the payload carries extra keys beyond the
      // standard tool-call/tool-result shape — that's the data
      // inline rendering doesn't cover.
      if (item.kind === 'tool_call') {
        const allowed = new Set(['tool_name', 'tool_call_id', 'arguments']);
        if (keys.every((k) => allowed.has(k))) return false;
      }
      if (item.kind === 'tool_result') {
        const allowed = new Set([
          'tool_name',
          'tool_call_id',
          'arguments',
          'success',
          'result',
        ]);
        if (keys.every((k) => allowed.has(k))) return false;
      }

      return true;
    },

    formatPayload(payload: unknown): string {
      try {
        return JSON.stringify(payload, null, 2);
      } catch {
        return String(payload);
      }
    },

    /** Relative-then-absolute time format, shared with the activity
     *  page and dashboard widget so the same row format renders the
     *  same way everywhere. */
    formatTime(iso: string): string {
      return formatRelativeTime(iso, (k, p) => this.$t(k, p));
    },

    /** Localize the row's primary summary line.
     *
     *  Backend derives a stable ``summary_key`` from the audit row's
     *  kind + entity (e.g. ``approved_tool``, ``issue_updated``) and
     *  passes any dynamic parts via ``summary_args`` (``{tool: ...}``,
     *  ``{title: ...}``).  We resolve that with ``$t`` using a
     *  ``timeline_<key>`` flat-key convention (matches the rest of
     *  this codebase's i18n table).  When:
     *
     *    * ``summary_key`` is missing (older audit row, kind we
     *      haven't mapped) — fall back to the English ``summary``.
     *    * The locale doesn't have the key — Tolgee returns the
     *      key itself; we detect that and fall back too.  Without
     *      this guard, German users would see literal
     *      ``timeline_approved_tool`` text on un-translated kinds.
     *
     *  The fallback is the same English string the backend used to
     *  render before this change, so the worst case is "untranslated"
     *  not "broken". */
    renderSummary(item: DocNetTimelineEvent): string {
      const fallback = () => formatSummary(item.summary, (k) => this.$t(k));
      if (!item.summary_key) return fallback();
      const fullKey = `timeline_${item.summary_key}`;
      const args = item.summary_args ?? {};
      const translated = this.$t(fullKey, args);
      // Tolgee returns the key as-is when no translation exists.
      // Detect that and fall back to the backend's English summary
      // so we never show a raw key to end-users.
      if (translated === fullKey) return fallback();
      return translated;
    },

    /** Icon for the rail dot.  Delegates to the shared
     *  ``actionIcon`` using ``kind`` as the action key — covers
     *  audit-style actions and timeline-only kinds.  One source-
     *  aware override: ``commented`` from ``mission_audit`` is an
     *  inbox-HITL redirect (the human blocked the proposed tool
     *  with a guidance message), not a posted issue chat.  Use
     *  the same ``cancel`` icon as ``rejected`` so a glance at
     *  the rail reads "tool was blocked" — the amber color from
     *  ``iconColor`` then distinguishes it from a bare reject's
     *  red.  ``commented`` from ``issue_activity`` (real chat)
     *  keeps the neutral ``chat_bubble_outline``. */
    iconFor(item: DocNetTimelineEvent): string {
      if (item.kind === 'commented' && item.source === 'mission_audit') {
        return 'cancel';
      }
      // Failed tool_result: ``actionIcon`` returns ``check_circle``
      // for every tool_result.  Combined with ``iconColor``'s red
      // override that produced a "red checkmark" — visually
      // contradictory.  Swap to ``error`` so the icon shape itself
      // says "this failed".
      if (
        item.source === 'agent_run_event'
        && item.kind === 'tool_result'
        && (item.payload as { success?: boolean } | null)?.success === false
      ) {
        return 'error';
      }
      return actionIcon(item.kind);
    },

    /** Quasar color for the rail dot.  Reuses the shared
     *  ``actionColor`` map with two source-aware overrides:
     *
     *    * ``tool_result`` failures (``payload.success === false``)
     *      upgrade to ``negative`` so failed tool calls visibly
     *      stand out from successful ones.
     *
     *    * ``commented`` rows from ``mission_audit`` are inbox-
     *      HITL redirects (the human typed guidance, the proposed
     *      tool was BLOCKED).  Render amber so the dot reads as
     *      "agent paused, needs to take a different action" —
     *      matching the amber accent on the drawer.  ``commented``
     *      from ``issue_activity`` is just a posted issue comment
     *      with no action semantics, so it stays neutral. */
    iconColor(item: DocNetTimelineEvent): string {
      if (
        item.source === 'agent_run_event'
        && item.kind === 'tool_result'
        && (item.payload as { success?: boolean } | null)?.success === false
      ) {
        return 'negative';
      }
      if (item.kind === 'commented' && item.source === 'mission_audit') {
        return 'warning';
      }
      return actionColor(item.kind);
    },

    /** Structured ``{key, from, to}`` for any single-field delta in
     *  the row's payload, or ``null`` when the payload isn't a clean
     *  delta.  The template uses ``key`` to decide between badge and
     *  text rendering: status flips get the ``<StatusBadge>`` for
     *  visual parity with mission/issue cards; other keys render as
     *  inline text. */
    deltaPair(item: DocNetTimelineEvent): {
      key: string;
      from: string;
      to: string;
    } | null {
      const payload = (item.payload || {}) as {
        old?: Record<string, unknown> | null;
        new?: Record<string, unknown> | null;
      };
      return inlineChangePair(payload.old, payload.new);
    },

    /** True when ``payload`` is a ``{old, new}`` audit shape whose
     *  every leaf on both halves is primitive (string, number,
     *  boolean, or null).  These rows are fully represented by the
     *  summary text + (when applicable) the ``<StatusBadge>`` pair —
     *  expanding to JSON would just duplicate the same facts (often
     *  with a bare UUID where the summary already shows the resolved
     *  name).  Anything non-primitive (nested objects, arrays of
     *  structs) bails out so the chevron stays available. */
    _isAllPrimitiveDelta(payload: Record<string, unknown>): boolean {
      const isPrimitive = (v: unknown): boolean =>
        v === null
        || typeof v === 'string'
        || typeof v === 'number'
        || typeof v === 'boolean';
      const sideAllPrimitive = (side: unknown): boolean => {
        if (side === null || side === undefined) return true;
        if (typeof side !== 'object' || Array.isArray(side)) {
          return isPrimitive(side);
        }
        return Object.values(side).every(isPrimitive);
      };
      return (
        sideAllPrimitive((payload as { old?: unknown }).old)
        && sideAllPrimitive((payload as { new?: unknown }).new)
      );
    },

    /** True when the delta is a status flip — drives the choice
     *  between ``<StatusBadge>`` rendering and inline-text fallback.
     *  Both mission and issue audits emit the change as
     *  ``{old: {status}, new: {status}}``, so the same key check
     *  covers both. */
    isStatusDelta(item: DocNetTimelineEvent): boolean {
      return this.deltaPair(item)?.key === 'status';
    },

    /** True for ``tool_call`` and ``tool_result`` rows — used by the
     *  caption to drop the duplicated ``tool_name`` (the summary
     *  already says "Tool: X"). */
    isToolEvent(item: DocNetTimelineEvent): boolean {
      return item.source === 'agent_run_event';
    },

    /** Tool args from the row's payload, or ``null`` when there are
     *  none worth rendering.  ``null`` is the explicit "skip the
     *  block" signal — empty-args calls (``list_agents``,
     *  ``get_child_issues``, ...) keep the row compact. */
    toolArgs(item: DocNetTimelineEvent): Record<string, unknown> | null {
      if (item.kind !== 'tool_call') return null;
      const args = (item.payload as { arguments?: Record<string, unknown> } | null)
        ?.arguments;
      if (!args || typeof args !== 'object' || Object.keys(args).length === 0) {
        return null;
      }
      return args;
    },

    /** Tool args carried on an inbox-act audit row (Approved/
     *  Rejected/Commented).  Source is ``commentInfo(item).toolCall.
     *  arguments`` — populated by ``inbox_service.act_on_item`` from
     *  the original inbox item's ``_tool_call`` blob.  Returns
     *  ``null`` when the row has no proposed tool call (e.g. an
     *  inbox dismiss not tied to a specific tool) or when the
     *  arguments object is empty.  Same shape as ``toolArgs`` so
     *  the template can reuse the ``timeline-args`` grid. */
    inboxToolArgs(item: DocNetTimelineEvent): Record<string, unknown> | null {
      const info = this.commentInfo(item);
      const args = info?.toolCall?.arguments;
      if (!args || typeof args !== 'object' || Array.isArray(args)) return null;
      const obj = args as Record<string, unknown>;
      if (Object.keys(obj).length === 0) return null;
      return obj;
    },

    /** Pretty-print a single arg value for the table.  Strings render
     *  bare (the row already conveys "string"); everything else
     *  becomes JSON so nested objects/arrays stay inspectable. */
    formatArgValue(value: unknown): string {
      if (value === null) return 'null';
      if (typeof value === 'string') return value;
      if (typeof value === 'number' || typeof value === 'boolean') {
        return String(value);
      }
      try {
        return JSON.stringify(value);
      } catch {
        return String(value);
      }
    },

    /** Tool result summary: ``{success, preview}`` for ``tool_result``
     *  rows, ``null`` for any other event.
     *
     *  Preview generation lives in ``timelinePreview.ts`` so the
     *  same heuristic applies to every tool — past, present, and
     *  future.  The formatter prefers human-readable fields
     *  (``name``, ``title``, ``status``) over machine fields
     *  (UUIDs, timestamps), so a ``list_projects`` response renders
     *  ``"3 projects: Invoices Q2, Test2, Test"`` instead of a wall
     *  of IDs.  Tools the formatter doesn't recognize fall back to
     *  noise-stripped compact JSON — still better than raw, never
     *  worse, no per-tool maintenance.
     *
     *  Tool returns can be either a parsed object (when the backend
     *  ``on_tool_end`` recognized JSON) or a string (legacy rows /
     *  non-JSON tool returns).  The formatter handles both — for
     *  strings it tries to parse as JSON first, then falls through
     *  to the string itself if parsing fails. */
    toolResult(item: DocNetTimelineEvent): {
      success: boolean | undefined;
      preview: string;
    } | null {
      if (item.kind !== 'tool_result') return null;
      const payload = (item.payload || {}) as {
        success?: boolean;
        result?: unknown;
      };
      let result: unknown = payload.result;
      // Legacy rows persisted ``result`` as ``str(result)[:500]``;
      // try to parse so the structured formatter can do its job.
      if (typeof result === 'string') {
        try {
          result = JSON.parse(result);
        } catch {
          /* leave as string — formatter renders it bare */
        }
      }
      const preview = formatToolResultPreview(result);
      return { success: payload.success, preview };
    },

    /** Comment block info: rendered HTML (collapsed teaser or full
     *  preview) plus enough metadata to drive the chevron + an
     *  "Open in issue" link when the writer truncated the comment.
     *
     *  ``html``      — sanitized Markdown HTML for the current state.
     *                  Collapsed shows ~280 chars of the preview;
     *                  expanded shows the full persisted preview
     *                  (capped at 1500 chars at write time).
     *  ``truncated`` — true when the original comment exceeded the
     *                  writer's cap (full body lives in
     *                  ``IssueComment.text``, reachable via the
     *                  issue page).
     *  ``issueId``   — the issue the comment belongs to, used to
     *                  build the deep-link.  Falls back to
     *                  ``item.issue_id`` since both the activity
     *                  writer and the audit writer carry it.
     *
     *  Returns ``null`` for non-comment rows / missing preview.
     */
    commentInfo(item: DocNetTimelineEvent): {
      html: string;
      loading: boolean;
      issueId: string | null;
      /** Inbox-act rows: the tool the agent proposed.  When set,
       *  the drawer renders an "Arguments" block above ``html``
       *  so the human's response (in ``html``) is visually paired
       *  with what they responded TO — instead of the args being
       *  buried in raw JSON or missing entirely. */
      toolCall?: { name: string | null; arguments: unknown } | null;
      /** Visual accent for the drawer.
       *    * ``positive`` (green) — ``approved``: tool ran.
       *    * ``negative`` (red)   — ``rejected`` / ``dismissed``:
       *                             tool blocked, hard veto.
       *    * ``warning`` (amber)  — ``commented``: tool redirected
       *                             with human guidance; agent
       *                             needs to take a different
       *                             action.  Sits between approve
       *                             and reject — the human didn't
       *                             veto outright, but the original
       *                             proposal didn't run either.
       *    * ``undefined``        — neutral (reassign etc.). */
      accent?: 'positive' | 'negative' | 'warning' | undefined;
    } | null {
      // Four kinds of rows render as Markdown comment bodies:
      //
      //   * ``comment_added`` / ``commented`` — child-issue
      //     comments persisted on ``IssueComment``.  The full body
      //     is lazy-fetched via ``comment_id``; the row's payload
      //     carries a truncated ``preview`` for the in-flight
      //     spinner state.
      //
      //   * ``agent_response`` / ``user_message`` — orchestrator
      //     responses and user follow-up messages mirrored into
      //     ``audit_logs`` so the timeline shows the back-and-forth
      //     alongside everything the agent did.  Full text lives in
      //     ``audit_log.new_values.text`` (no lazy fetch — bounded
      //     and already on the row).
      //
      //   * ``approved`` / ``rejected`` / ``commented`` /
      //     ``dismissed`` / ``reassigned`` / ``acted:*`` — inbox
      //     decisions.  When the human attached a comment to the
      //     decision (a reject reason or a plain comment), it
      //     lives in ``new_values.resolution_notes``.  Same
      //     symmetry as user mission messages: the verb is in the
      //     header, the human's text expands in the drawer.
      //
      // All share the same render path: collapsed → null
      // (header-only); expanded → ``renderMarkdown(text)``.
      // ``commented`` is overloaded across two sources — the
      // child-issue activity log (preview + lazy-fetched body) and
      // the mission-audit inbox-act log (resolution_notes).  Pick
      // the path by ``source`` so the inbox variant doesn't fall
      // into the issue-comment branch and silently return null.
      const isIssueComment =
        item.kind === 'comment_added'
        || (item.kind === 'commented' && item.source === 'issue_activity');
      const isAgentResponse =
        item.kind === 'agent_response' || item.kind === 'user_message';
      const isInboxAct =
        item.kind === 'approved'
        || item.kind === 'rejected'
        || item.kind === 'reassigned'
        || item.kind === 'dismissed'
        || (item.kind === 'commented' && item.source === 'mission_audit')
        || (typeof item.kind === 'string' && item.kind.startsWith('acted:'));
      if (!isIssueComment && !isAgentResponse && !isInboxAct) return null;

      let text: string | null = null;
      let commentId: string | null = null;
      let toolCall: { name: string | null; arguments: unknown } | null = null;
      let accent: 'positive' | 'negative' | 'warning' | undefined;

      if (isIssueComment) {
        const payload = (item.payload || {}) as {
          preview?: unknown;
          comment_id?: unknown;
        };
        const preview = payload.preview;
        if (typeof preview !== 'string' || !preview.trim()) return null;
        text = preview;
        commentId =
          typeof payload.comment_id === 'string' ? payload.comment_id : null;
      } else if (isAgentResponse) {
        // Audit-row payload shape: ``{old, new}``.  Agent
        // responses carry the full text in ``new.text``.
        const payload = (item.payload || {}) as {
          new?: { text?: unknown } | null;
        };
        const fullText = payload.new?.text;
        if (typeof fullText !== 'string' || !fullText.trim()) return null;
        text = fullText;
        // ``user_message`` rows get the warm warning accent so
        // the message blockquote (orange left rule + tinted
        // background) matches the orange rail dot we set in
        // ``actionColor``.  Without this the body reverts to
        // the default primary-blue left rule and looks
        // disconnected from the dot.  ``agent_response`` rows
        // stay neutral — they're the common case and the
        // chevron-expanded body looks busy if every one carries
        // an accent.
        if (item.kind === 'user_message') {
          accent = 'warning';
        }
      } else {
        // Inbox-act audit row.  Two pieces of optional content:
        //   * ``resolution_notes`` — what the human typed.
        //   * ``tool_call`` — what the agent proposed (carried
        //     forward from the inbox item by the audit writer).
        // Render whichever is present.  If BOTH are missing the
        // drawer has nothing to show, so return null and the
        // chevron stays hidden.
        const payload = (item.payload || {}) as {
          new?: {
            resolution_notes?: unknown;
            tool_call?: { tool_name?: unknown; arguments?: unknown } | null;
          } | null;
        };
        const notes = payload.new?.resolution_notes;
        const tc = payload.new?.tool_call;
        const hasNotes = typeof notes === 'string' && !!notes.trim();
        if (hasNotes) text = notes as string;
        if (tc && typeof tc === 'object') {
          toolCall = {
            name: typeof tc.tool_name === 'string' ? tc.tool_name : null,
            arguments: tc.arguments ?? null,
          };
        }
        if (!hasNotes && !toolCall) return null;
        // Visual accent reads the kind directly so ``acted:*``
        // custom actions land on the same treatment as their
        // canonical equivalents.  ``commented`` is amber: the
        // human didn't veto, they redirected — the original tool
        // didn't run, but the agent has new guidance to act on.
        // Distinct from ``rejected`` (hard veto) and ``approved``
        // (tool ran).
        if (
          item.kind === 'rejected'
          || item.kind === 'acted:reject'
          || item.kind === 'dismissed'
        ) {
          accent = 'negative';
        } else if (item.kind === 'approved' || item.kind === 'acted:approve') {
          accent = 'positive';
        } else if (
          item.kind === 'commented'
          || item.kind === 'acted:comment'
        ) {
          accent = 'warning';
        }
      }

      // Inbox-act rows (``approved`` / ``rejected`` /
      // ``commented`` / ``dismissed`` / ``acted:*`` from
      // ``mission_audit``) get inline-visible message rendering
      // — the human's reason IS the event, hiding it behind a
      // chevron makes the timeline lie about what just
      // happened.  This pairs with the always-inline args grid
      // above so HITL-resolved tool calls have the same scan
      // rhythm as auto-approved ``Tool: ...`` rows.
      //
      // ``agent_response`` / ``user_message`` / ``comment_added``
      // (issue chat) keep the existing "header-only when
      // collapsed, full body when expanded" pattern — those
      // bodies are long-form prose that would dominate the
      // timeline if always-visible, and the row's summary
      // already shows a one-line preview.
      const isExpanded = this.expanded.has(item.event_id);
      if (!isExpanded && !isInboxAct) return null;

      // Expanded (or HITL redirect, always inline): prefer the
      // lazy-fetched full body when this is an issue comment
      // with a comment_id; for agent_response rows the full text
      // is already in the payload, no fetch round-trip needed.
      const fullText = commentId
        ? this.fullCommentBodies[commentId]
        : undefined;
      const isLoading = commentId
        ? this.loadingCommentIds.has(commentId) && !fullText
        : false;
      return {
        html: text ? renderMarkdown(fullText ?? text) : '',
        loading: isLoading,
        issueId: item.issue_id ?? null,
        toolCall,
        accent,
      };
    },
  },
});
</script>

