/**
 * Generic preview formatter for tool result payloads.
 *
 * Goal: turn arbitrary tool returns into a one-line, human-scannable
 * preview that surfaces the *names* a human cares about (project
 * names, user names, statuses) instead of the *IDs* the agent uses
 * to wire things up.
 *
 * Why generic and not per-tool:
 *   New tools get added regularly.  A per-tool summarizer table
 *   means every new tool ships with empty preview UX until someone
 *   writes a summarizer; tools never written for grow stale forever.
 *   A generic formatter that reads the structure and prefers
 *   human-friendly fields covers the long tail without per-tool
 *   maintenance.  Per-tool summarizers can be layered on later for
 *   the hottest tools if the generic output proves insufficient.
 *
 * Heuristic rules (applied in order):
 *   1. Single primitive          → render directly.
 *   2. Top-level array of objects → ``"<n> <plural>: <name>, <name>, …"``
 *   3. Object with a ``items``/``rows``/``data``/``projects``/``users``/...
 *      array property                → recurse into that array (rule 2).
 *   4. Object with success: bool   → strip success (already rendered as
 *                                      chip), recurse on the rest.
 *   5. Object with one obvious "name" field
 *                                  → ``"<name> (<short id?>)"``
 *   6. Object otherwise            → drop UUIDs, prefer names — render
 *                                      remaining shape as compact JSON.
 *
 * The point isn't perfect formatting; it's avoiding wall-of-UUIDs
 * in the most common shapes (lists of records, single record returns).
 */

const MAX_PREVIEW_CHARS = 280;

/** Field names worth showing to humans, in priority order.  First
 *  match wins — used to label list entries and pick the "primary"
 *  display field of a single-record response. */
const NAMEY_FIELDS = ['name', 'title', 'subject', 'label', 'filename'] as const;

/** Field names that exist for machines, not humans.  Stripped from
 *  rendered previews unless they're the *only* useful field. */
const MACHINE_FIELDS = new Set([
  'id',
  'org_id',
  'project_id',
  'mission_id',
  'issue_id',
  'document_id',
  'doc_id',
  'agent_id',
  'user_id',
  'created_on',
  'created_at',
  'last_modified_on',
  'last_modified_at',
  'updated_at',
  'is_deleted',
]);

/** Heuristic UUID detector — strict enough to not eat real strings. */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Plural-ish label for a list, derived from the wrapping key when
 *  one exists — ``{projects: [...]}`` → "projects", ``[...]`` → "items". */
function pluralLabelFromKey(key: string | null): string {
  if (!key) return 'items';
  return key;
}

/** First non-empty value among the namey fields, or ``null``. */
function pickNameyField(obj: Record<string, unknown>): string | null {
  for (const k of NAMEY_FIELDS) {
    const v = obj[k];
    if (typeof v === 'string' && v.trim().length > 0) return v;
  }
  return null;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return (
    typeof v === 'object'
    && v !== null
    && !Array.isArray(v)
    && Object.getPrototypeOf(v) === Object.prototype
  );
}

/** Recursively strip UUID values + machine-only fields.  Used right
 *  before JSON-stringifying as the fallback render so the preview
 *  doesn't dominate with ``id`` columns no human will read. */
function stripNoise(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stripNoise);
  if (isPlainObject(value)) {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) {
      if (MACHINE_FIELDS.has(k)) continue;
      if (typeof v === 'string' && UUID_RE.test(v)) continue;
      out[k] = stripNoise(v);
    }
    return out;
  }
  return value;
}

/** Format a list of objects as ``"<n> <label>: <name1>, <name2>, …"``.
 *  Falls back to compact JSON when no namey field is found across
 *  the entries. */
function formatList(items: unknown[], label: string): string {
  if (items.length === 0) return `0 ${label}`;
  const names: string[] = [];
  for (const it of items) {
    if (isPlainObject(it)) {
      const n = pickNameyField(it);
      if (n) {
        names.push(n);
        continue;
      }
    }
    if (typeof it === 'string' || typeof it === 'number') {
      names.push(String(it));
    }
  }
  if (names.length === 0) {
    // Couldn't extract names — render compact stripped JSON instead.
    return JSON.stringify(stripNoise(items));
  }
  const head = names.slice(0, 5).join(', ');
  const more = names.length > 5 ? `, +${names.length - 5} more` : '';
  return `${items.length} ${label}: ${head}${more}`;
}

/**
 * Build a one-line, human-readable preview from a tool result payload.
 *
 * Returns ``''`` when the payload is empty/undefined (caller decides
 * whether to render anything).  Always trimmed, single-spaced, and
 * truncated to ``MAX_PREVIEW_CHARS``.
 */
export function formatToolResultPreview(result: unknown): string {
  let preview = '';

  // Primitive — render bare.
  if (result === null || result === undefined) {
    preview = '';
  } else if (
    typeof result === 'string'
    || typeof result === 'number'
    || typeof result === 'boolean'
  ) {
    preview = String(result);
  } else if (Array.isArray(result)) {
    // Top-level array: list-of-things.
    preview = formatList(result, 'items');
  } else if (isPlainObject(result)) {
    // Strip ``success`` since the chip already shows it; recurse.
    const obj = { ...result };
    delete obj.success;

    // Find a wrapping array property (``{projects: [...]}``).  This
    // covers the common ``list_*`` tool shape.
    const arrayEntry = Object.entries(obj).find(([, v]) => Array.isArray(v));
    if (arrayEntry) {
      const [key, arr] = arrayEntry;
      preview = formatList(arr as unknown[], pluralLabelFromKey(key));
    } else {
      // Single-record response.  Prefer the namey field if there is
      // one — gives ``"INVOICE"``, ``"My document.pdf"``, etc.
      const namey = pickNameyField(obj);
      if (namey) {
        preview = namey;
      } else {
        // Fallback: stripped compact JSON.  Keeps numeric/status fields
        // visible without burying the row under UUIDs.  When the
        // strip leaves nothing readable (the only fields were
        // UUIDs/timestamps/etc.), don't render an empty ``{}`` —
        // the success chip already says everything that's left.
        const stripped = stripNoise(obj);
        const isEmptyAfterStrip = (
          isPlainObject(stripped) && Object.keys(stripped).length === 0
        );
        preview = isEmptyAfterStrip ? '' : JSON.stringify(stripped);
      }
    }
  } else {
    // Unknown type.
    try {
      preview = JSON.stringify(result);
    } catch {
      preview = String(result);
    }
  }

  preview = preview.replace(/\s+/g, ' ').trim();
  if (preview.length > MAX_PREVIEW_CHARS) {
    preview = preview.slice(0, MAX_PREVIEW_CHARS).trimEnd() + '…';
  }
  return preview;
}
